assert_columns "catalog_products" "id:NO;name:NO;price:NO;stock:NO"
assert_type "catalog_products" "id" "integer"
assert_type "catalog_products" "name" "text"
assert_type "catalog_products" "price" "money"
assert_type "catalog_products" "stock" "integer"
# Test descriptions are in English. SQL assertions use the isolated test database.
assert_equals "Product names can exceed the original length" "SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='catalog_products' AND COLUMN_NAME='name' AND CHARACTER_MAXIMUM_LENGTH>40" "1"
assert_equals "catalog_products.price preserves its original format" "SELECT COLUMN_TYPE FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='catalog_products' AND COLUMN_NAME='price'" "decimal(8,2)"
assert_equals "Original products and prices are preserved" "SELECT GROUP_CONCAT(CONCAT(id,':',name,':',price) ORDER BY id) FROM catalog_products" "1:Chitarra:129.90,2:Piano:799.00"
assert_equals "Existing products receive zero stock" "SELECT SUM(stock) FROM catalog_products" "0"
assert_equals "Old tables are removed" "SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('products','import_buffer')" "0"
assert_equals "The obsolete column is removed" "SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='catalog_products' AND COLUMN_NAME='legacy_code'" "0"
assert_rejects "Negative stock is rejected" "3819|1264" "UPDATE catalog_products SET stock=-1 WHERE id=1"
